import subprocess, sys, os, json, datetime

BASE = r"E:\Project Software\Orion"
CHECKER = os.path.join(BASE, "output", "scripts", "cek_kondisi_realtime.py")
LAPORAN = os.path.join(BASE, "memory", "laporan_kondisi.json")
LOG = os.path.join(BASE, "memory", "weker_log.txt")
SINYAL = os.path.join(BASE, "memory", "sinyal_inisiatif.json")

def log(pesan):
    try:
        waktu = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with open(LOG, "a", encoding="utf-8") as f:
            f.write("[" + waktu + "] " + pesan + "\n")
    except Exception:
        pass

def jalankan_checker():
    try:
        hasil = subprocess.run([sys.executable, CHECKER],
                               capture_output=True, text=True, timeout=60)
        return hasil.returncode == 0
    except Exception as e:
        log("ERROR checker: " + str(e))
        return False

